CREATE TABLE IF NOT EXISTS user (id INTEGER PRIMARY KEY AUTOINCREMENT, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, real_name VARCHAR(50), phone VARCHAR(20), role VARCHAR(20) NOT NULL DEFAULT 'student', is_initialized INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS building (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(50) NOT NULL UNIQUE, gender VARCHAR(10) NOT NULL);
CREATE TABLE IF NOT EXISTS dormitory (id INTEGER PRIMARY KEY AUTOINCREMENT, dormitory_number VARCHAR(80) NOT NULL UNIQUE, building VARCHAR(50), room_type VARCHAR(20), capacity INTEGER NOT NULL DEFAULT 4, current_count INTEGER NOT NULL DEFAULT 0, gender VARCHAR(10), remark VARCHAR(200), CHECK(capacity > 0 AND current_count >= 0 AND current_count <= capacity));
CREATE TABLE IF NOT EXISTS student (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(50) NOT NULL, student_id VARCHAR(20) NOT NULL UNIQUE, grade VARCHAR(10) NOT NULL, class_name VARCHAR(50), gender VARCHAR(10), phone VARCHAR(20) NOT NULL, dormitory_number VARCHAR(80), is_dormitory_leader INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS repair_request (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id VARCHAR(20) NOT NULL, student_name VARCHAR(50) NOT NULL, dormitory_number VARCHAR(80) NOT NULL, repair_type VARCHAR(50) NOT NULL, description TEXT, image_path VARCHAR(200), status VARCHAR(20) NOT NULL DEFAULT '待处理', create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_student_dormitory ON student(dormitory_number);
CREATE INDEX IF NOT EXISTS idx_repair_student ON repair_request(student_id);
